<script setup lang="ts">
import {computed,ref,onBeforeUnmount} from 'vue';
import {useLab} from '../store';
import {type Table,exportText} from '../api';
import ResultTable from '../components/ResultTable.vue';
const lab=useLab();const selected=ref('');const choice=ref(-1);const feedback=ref<{correct:boolean,table:Table,explanation:string}>();
const checkpoint=computed(()=>lab.predictions.find(p=>p.id===selected.value));
const offline=computed(()=>lab.questions.filter(q=>q.engine==='sqlite'));
const passed=computed(()=>offline.value.filter(q=>lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]==='passed').length);
const order=['relation','projection','where','null','like','count','aggregate','join','left','subquery','correlated','exists','union','except','keys','constraint','create','alter','update','delete','view','index','trigger','algebra-filter','algebra-join','rollback','recovery','isolation','snapshot','schedule','view-schedule'];
const next=computed(()=>[...offline.value].sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id)).find(q=>lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]!=='passed')?.id??'relation');
const resume=computed(()=>{const last=lab.workspace?.learning.last_question;return last&&lab.workspace?.progress[`${last}@${lab.workspace.exercise_seed}`]!=='passed'?last:next.value});
onBeforeUnmount(()=>lab.invalidateJobs(['prediction']));
function mode(value:string){lab.workspace!.learning.mode=value;lab.markDirty();}
async function predict(){if(!checkpoint.value||choice.value<0)return;const id=checkpoint.value.id;const r=await lab.run<{correct:boolean,table:Table,explanation:string}>('prediction','predict',{id,choice:choice.value});if(r&&checkpoint.value?.id===id){feedback.value=r;lab.workspace!.learning.predictions[id]=r.correct;lab.markDirty();}}
function choose(id:string){lab.invalidateJobs(['prediction']);selected.value=id;choice.value=-1;feedback.value=undefined;}
async function report(){await exportText(`# 学习记录\n\n离线主线：${passed.value}/${offline.value.length}\n\n`+Object.entries(lab.workspace!.learning.attempts).map(([k,p])=>`- ${k}：${p?.status}，${p?.attempts} 次，${p?.assisted?'辅助':'独立'}作答`).join('\n'),'学习记录.md');}
</script>
<template><div class="lab-page learning-page"><header class="page-heading"><div><span class="eyebrow">LEARN · EXPLORE · UNDERSTAND</span><h1>从一个问题开始，亲手验证答案</h1><p>预测 → 实验 → 解释 → 应用。引导可以跳过，所有章节都可直接访问。</p></div><button @click="report().catch(lab.fail)">导出学习记录</button></header><div class="learning-entry"><button class="primary" data-testid="start-learning" @click="lab.study('relation')">从零开始</button><button @click="lab.study(resume)">继续学习</button><button @click="lab.page='ide'">进入自由实验</button><button @click="lab.page='cases'">案件：第 41 个人</button></div><div class="learning-summary"><strong>离线主线 {{passed}} / {{offline.length}}</strong><p>MySQL 专属练习单独统计，需要真实服务；不影响完成离线主线。</p><label>学习方式 <select :value="lab.workspace?.learning.mode||'guided'" @change="mode(($event.target as HTMLSelectElement).value)"><option value="guided">引导：先预测，再验证</option><option value="free">自由：直接实验</option></select></label></div><h2>六段入门引导</h2><div class="lesson-grid"><article v-for="(lesson,i) in lab.lessons" :key="lesson.id"><span class="eyebrow">0{{i+1}}</span><h3>{{lesson.title}}</h3><p>{{lesson.explanation}}</p><button @click="lab.study(lesson.question)">开始这个实验</button></article></div><h2>八个预测检查点</h2><p>先想一想，再看真实 SQLite 的返回。预测错误不会阻止继续学习。</p><div class="checkpoint-list"><button v-for="p in lab.predictions" :key="p.id" :class="{active:selected===p.id}" @click="choose(p.id)">{{lab.workspace?.learning.predictions[p.id]?'✓ ':''}}{{p.title}}</button></div><section v-if="checkpoint" class="prediction-panel"><h3>{{checkpoint.prompt}}</h3><label v-for="(c,i) in checkpoint.choices" :key="c"><input v-model="choice" type="radio" :value="i" name="prediction">{{c}}</label><div class="toolbar"><button class="primary" :disabled="choice<0||!!lab.jobs.prediction" @click="predict">执行并验证预测</button><button @click="choose('')">跳过</button></div><div v-if="feedback" role="status"><strong>{{feedback.correct?'预测与引擎结果一致':'观察结果，再调整理解'}}</strong><p>{{feedback.explanation}}</p><ResultTable :table="feedback.table" compact/></div><details><summary>查看验证 SQL</summary><pre>{{checkpoint.sql}}</pre></details></section><h2>完整课程与错题</h2><p>保留课件的 17 个章节编号。课程练习中可查看全部章节及错题。</p><button @click="lab.study(next)">继续最近未完成练习</button></div></template>
